// JSON Schema of the content source format (`wb content schema`, generated by `pnpm gen`)
// prepared for @rjsf forms: nullable unions become their plain type, since a missing
// optional field is simply not written.
import type { RJSFSchema, UiSchema } from '@rjsf/utils';
import raw from '../../../packages/protocol/src/generated/content.schema.json';

type Json = Record<string, unknown>;

function simplify(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(simplify);
  if (!v || typeof v !== 'object') return v;
  const o = { ...(v as Json) };
  const t = o['type'];
  if (Array.isArray(t)) {
    const rest = t.filter((x) => x !== 'null');
    o['type'] = rest.length === 1 ? rest[0] : rest;
  }
  for (const key of ['anyOf', 'oneOf'] as const) {
    const alts = o[key];
    if (Array.isArray(alts)) {
      const rest = alts.filter((a) => !(a && typeof a === 'object' && (a as Json)['type'] === 'null'));
      if (rest.length === 1 && rest.length < alts.length) {
        delete o[key];
        Object.assign(o, rest[0] as Json);
      } else o[key] = rest;
    }
  }
  if (o['default'] === null) delete o['default'];
  for (const [k, x] of Object.entries(o)) o[k] = simplify(x);
  return o;
}

const kinds = (raw as { kinds: Record<string, unknown> }).kinds;
const cache = new Map<string, RJSFSchema>();

export function schemaFor(kind: string): RJSFSchema | null {
  if (!kinds[kind]) return null;
  let s = cache.get(kind);
  if (!s) {
    s = simplify(kinds[kind]) as RJSFSchema;
    cache.set(kind, s);
  }
  return s;
}

const design: UiSchema = { archetype: { 'ui:widget': 'archetype' }, note: { 'ui:widget': 'textarea', 'ui:options': { rows: 2 } } };

/** Custom widgets of doc 04 §5: RCS by aspect, stations, magazine mix; archetype picker. */
export function uiFor(kind: string): UiSchema {
  const base: UiSchema = {
    'ui:order': ['id', 'kind', 'name', 'short_name', 'custom', 'extends', 'overrides', 'category', 'design', '*'],
    kind: { 'ui:widget': 'hidden' },
    design,
    'ui:submitButtonOptions': { norender: true },
  };
  if (kind === 'platform') {
    return { ...base, signature: { rcs_m2: { 'ui:field': 'rcs' } }, stations: { 'ui:field': 'stations' } };
  }
  if (kind === 'system') {
    return { ...base, components: { items: { magazine: { 'ui:field': 'magazine' } } } };
  }
  return base;
}
